function renderFooter(){
  var st = stepAt(S.cur);
  /* 内嵌面板（作业 / 100 Days / 视频目录）开着时，底栏的"上一条 / 下一条"就是"退出面板"键，
     一点就把人踢出去，而且没有任何说明。所以面板开着时它们停用、点阵清空（点阵属于卡片）。 */
  var inPanel = surfaceIsInline();
  if ($("btnPrev")) $("btnPrev").disabled = inPanel || !(S.cur > 0);
  if ($("btnNext")) $("btnNext").disabled = inPanel || !(S.cur < S.steps.length - 1);
  if (inPanel){
    if ($("dots")) $("dots").innerHTML = "";
    if ($("dotCount")) $("dotCount").textContent = "";
  }
